problems.solution:
def neuron(x, w, b):
    """Lesson 6.1: weighted sum plus bias, then ReLU."""
    if len(x) != len(w):
        raise ValueError("one weight per input")
    return max(0, sum(wi * xi for wi, xi in zip(w, x)) + b)

def layer(x, W, b):
    """One weight row and one bias per neuron."""
    return [neuron(x, w_row, b_i) for w_row, b_i in zip(W, b)]

def network(x, params):
    for W, b in params:
        x = layer(x, W, b)
    return x

import numpy as np

def init_params(sizes, rng):
    params = []
    for n_in, n_out in zip(sizes[:-1], sizes[1:]):
        params.append((rng.normal(size=(n_out, n_in)), np.zeros(n_out)))
    return params

def forward(x, params):
    for W, b in params:
        x = np.maximum(0, W @ x + b)
    return x

def count_params(sizes):
    return sum(n_out * n_in + n_out for n_in, n_out in zip(sizes[:-1], sizes[1:]))
